116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto);
120	        prepareNewOwner(ownerFieldsDto, registrationDate);
121	        HttpHeaders headers = new HttpHeaders();
122	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
123	        owner.setRegistrationDate(registrationDate);
124	        owner.setCustomerCode(customerCodeFor(owner));
125	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
126	        assignHousehold(owner);
127	        applyPossibleDuplicate(owner, ownerFieldsDto);
128	        this.clinicService.saveOwner(owner);
129	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
130	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
131	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
132	            owner.getMembershipLevel(), owner.getMembershipNumber());
133	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
134	        ownerDto.setBulkSignupWarning(bulkSignupWarning(registrationDate));
135	        headers.setLocation(UriComponentsBuilder.newInstance()
136	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
137	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
143	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
144	        if (currentOwner == null) {
145	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
146	        }
147	        currentOwner.setAddress(ownerFieldsDto.getAddress());
148	        currentOwner.setCity(ownerFieldsDto.getCity());
149	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
150	        currentOwner.setLastName(ownerFieldsDto.getLastName());
151	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
152	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
153	        this.clinicService.saveOwner(currentOwner);
154	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Transactional
159	    @Override
160	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
